import pathlib,json,sqlite3,hashlib
root=pathlib.Path(__file__).parent;checks=[];observations=[]
def ck(w,n,v):checks.append({'workspace':w.name,'name':n,'ok':bool(v)})
for w in [root/'r5-demo-workspace',root/'clone-r5-demo-workspace']:
 c=sqlite3.connect('file:'+str(w/'state/followup.sqlite')+'?mode=ro',uri=True);c.row_factory=sqlite3.Row
 meta=json.loads((w/'state/service.json').read_text());log=[json.loads(x) for x in (w/'state/service.log').read_text().splitlines()];starts=[x for x in log if x['event']=='service.start'];stops=[x for x in log if x['event']=='service.stop'];tasks=list(c.execute('select * from tasks'));completed=[t for t in tasks if t['status']=='completed'];cancelled=[t for t in tasks if t['status']=='cancelled']
 ck(w,'real-clock-explicit-zone-config',meta['clock']=='real' and meta['timezone']=='UTC' and len(meta['configSha'])==64);ck(w,'three-distinct-service-processes',len(starts)==3 and len({x['pid'] for x in starts})==3);ck(w,'three-service-stops',len(stops)==3 and meta['state']=='stopped');ck(w,'no-clock-advance-events',c.execute("select count(*) from followup_events where kind='clock.advanced'").fetchone()[0]==0);ck(w,'one-completed-one-cancelled',len(tasks)==2 and len(completed)==len(cancelled)==1)
 t=completed[0];tid=t['ticket_id'];receipts=list(c.execute('select * from receipts where ticket_id=?',[tid]));ck(w,'one-receipt',len(receipts)==1);r=receipts[0];e=c.execute('select * from effects where effect_id=?',[r['effect_id']]).fetchone();a=json.loads(t['analysis_json']);done=json.loads(t['completion_json']);ref=json.loads(r['input_ref_json']);result=json.loads(t['result_json']);ck(w,'attempt-two',t['attempt']==2);ck(w,'successful-verified-receipt',r['ok']==1 and r['inputs_verified']==1 and not r['needs_reconciliation']);ck(w,'four-input-identities',ref==json.loads(e['input_ref_json'])==a['inputRef']==done['inputRef']);ck(w,'input-current-result',all(ref[k]==result[k] for k in ['runId','revision','resultPath','resultFileSha','artifactPath','artifactSha']));ck(w,'receipt-links-analysis-completion',r['receipt_id']==a['receiptId']==done['receiptId']);ck(w,'output-identity',r['output_path']==a['artifactPath'] and r['output_sha256']==a['artifactSha']==done['artifactSha'])
 for label,path,sha in [('result',ref['resultPath'],ref['resultFileSha']),('artifact',ref['artifactPath'],ref['artifactSha']),('snapshot','state/inputs/'+ref['resultFileSha']+'.json',ref['resultFileSha']),('output',r['output_path'],r['output_sha256'])]:ck(w,label+'-sha',hashlib.sha256((w/path).read_bytes()).hexdigest()==sha)
 ats=list(c.execute('select * from attentions where ticket_id=?',[tid]));cont=[x for x in ats if x['decision_key'].startswith('continuation:')];ck(w,'one-continuation-question',len(cont)==1);q=cont[0];ck(w,'service-delivered-during-first-run',starts[0]['at']<=q['delivered_at']<=stops[0]['at']);ck(w,'new-authorization-after-restart',q['answered_at']>=stops[1]['at']);ck(w,'visibility-before-new-authorization',q['delivered_at']<=q['answered_at']);ck(w,'receipt-after-new-authorization',q['answered_at']<=r['started_at']);ck(w,'old-input-rejection-kept',any(x.startswith('tool_input_rejected:') for x in json.loads(t['diagnostics_json'])))
 notifications=list(c.execute('select * from notifications where ticket_id=?',[tid]));ck(w,'no-duplicate-attention-notification',len(notifications)==len({x['attention_id'] for x in notifications}));ct=cancelled[0]['ticket_id'];ck(w,'cancelled-no-notifications',c.execute('select count(*) from notifications where ticket_id=?',[ct]).fetchone()[0]==0);ck(w,'cancelled-no-scheduled-jobs',c.execute("select count(*) from wake_jobs where ticket_id=? and status='scheduled'",[ct]).fetchone()[0]==0)
 duplicates=[dict(x) for x in c.execute("select ticket_id,task_revision,reason,decision_id,count(*) as jobs from wake_jobs where reason='quiet' group by ticket_id,task_revision,reason,decision_id having count(*)>1")];observations.append({'workspace':w.name,'serviceStops':stops,'duplicateLogicalQuietJobs':duplicates,'classification':'extra wake jobs for same logical waiting decision; demo passes despite these duplicates'});c.close()
result={'checks':len(checks),'failed':[x for x in checks if not x['ok']],'rows':checks,'observations':observations};(root/'independent-r5-demo.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'checks':len(checks),'failed':result['failed'],'observations':observations}));raise SystemExit(bool(result['failed']))
